INSERT INTO public.site_content (id, content, type)
VALUES 
('dynamic-pricing-restoration-content', '<h3>TARIFS RESTAURATION</h3><table border=\"1\" cellpadding=\"5\" style=\"border-collapse: collapse; width: 100%;\"><thead><tr style=\"background-color: #f8fafc;\"><th>Fréquentation</th><th>1er trimestre</th><th>2ème trimestre</th><th>3ème trimestre</th></tr></thead><tbody><tr><td>4 jours/semaine</td><td>90 € / <em style=\"color: grey;\">130 €</em></td><td>75 € / <em style=\"color: grey;\">115 €</em></td><td>65 € / <em style=\"color: grey;\">105 €</em></td></tr><tr><td>3 jours/semaine</td><td>70 € / <em style=\"color: grey;\">100 €</em></td><td>60 € / <em style=\"color: grey;\">90 €</em></td><td>45 € / <em style=\"color: grey;\">75 €</em></td></tr><tr><td>2 jours/semaine</td><td>50 € / <em style=\"color: grey;\">70 €</em></td><td>40 € / <em style=\"color: grey;\">60 €</em></td><td>30 € / <em style=\"color: grey;\">50 €</em></td></tr><tr><td>1 jour/semaine</td><td>25 € / <em style=\"color: grey;\">35 €</em></td><td>20 € / <em style=\"color: grey;\">35 €</em></td><td>15 € / <em style=\"color: grey;\">25 €</em></td></tr></tbody></table><p><small><em>Le second prix indiqué en gris et italique correspond au tarif applicable pour les familles qui ne peuvent en aucun cas assurer leur tour de surveillance au moins une fois par mois (cas des 2 parents qui travaillent). Il doit être utilisé à titre exceptionnel sur raisons motivées.</em></small></p>', 'text'),
('dynamic-pricing-tuition-content', '<h3>TARIF SCOLARITE</h3><p>Classes allant de la Grande Section au CM2 :</p><table border=\"1\" cellpadding=\"5\" style=\"border-collapse: collapse; width: 100%;\"><thead><tr style=\"background-color: #f8fafc;\"><th>Nombre d''enfants</th><th>Frais de scolarité / mois / enfant</th><th>Total</th></tr></thead><tbody><tr><td>1er enfant</td><td>205,00 €</td><td>205,00 €</td></tr><tr><td>2ème enfant (- 10 %)</td><td>185,00 €</td><td>390,00 €</td></tr><tr><td>3ème enfant (- 30 %)</td><td>144,00 €</td><td>534,00 €</td></tr><tr><td>4ème enfant (- 40 %)</td><td>123,00 €</td><td>657,00 €</td></tr><tr><td>5ème enfant (- 50 %)</td><td>103,00 €</td><td>760,00 €</td></tr><tr><td>6ème enfant (- 50 %)</td><td>103,00 €</td><td>863,00 €</td></tr></tbody></table><p>Classes de Petite et Moyenne Section : le prix mensuel s’élève à 100 €.</p>', 'text')
